        mockMvc.perform(post("/api/reopen-requests/{id}/confirmations", reopenId)
                .contentType(MediaType.APPLICATION_JSON)
                .content("{\"requestId\":\"ec-2\",\"role\":\"MAINTENANCE\"}"));
        assertThat(lineStatus()).isEqualTo("NORMAL");
