import static org.assertj.core.api.Assertions.assertThat;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import java.math.BigDecimal;
import java.time.LocalDateTime;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.http.MediaType;

/**
 * 风速阈值与 10 分钟窗口判定测试。
 */
class WindThresholdTest extends BaseIntegrationTest {

    private static final LocalDateTime T0 = LocalDateTime.of(2026, 1, 10, 9, 0, 0);

    @Test
    @DisplayName("9 分钟数据不触发：判定须恰满 10 分钟")
    void nineMinutesDoesNotTrigger() throws Exception {
        feedWind(segmentIds.get(0), T0, 9, new BigDecimal("25.00"), "nine-min");
        assertThat(lineStatus()).isEqualTo("NORMAL");
        assertThat(countRows("control_event")).isZero();
    }

    @Test
    @DisplayName("10 分钟平均恰达 17m/s 触发缓停（恰等阈值生效）")
    void exactlySeventeenTriggersSoftHold() throws Exception {
        feedWind(segmentIds.get(0), T0, 10, new BigDecimal("17.00"), "soft-eq");
        assertThat(lineStatus()).isEqualTo("SOFT_HOLD");
        assertThat(countRows("control_event")).isOne();
        String type = jdbc.queryForObject("SELECT event_type FROM control_event", String.class);
        String avg = jdbc.queryForObject("SELECT trigger_avg_speed FROM control_event", String.class);
        assertThat(type).isEqualTo("SOFT_HOLD");
        assertThat(new BigDecimal(avg)).isEqualByComparingTo("17.00");
    }

    @Test
    @DisplayName("10 分钟平均恰达 20m/s 触发紧急停车（恰等按高档处理）")
    void exactlyTwentyTriggersEmergencyStop() throws Exception {
        feedWind(segmentIds.get(0), T0, 10, new BigDecimal("20.00"), "emg-eq");
        assertThat(lineStatus()).isEqualTo("EMERGENCY_STOP");
        String type = jdbc.queryForObject("SELECT event_type FROM control_event", String.class);
        assertThat(type).isEqualTo("EMERGENCY_STOP");
    }

    @Test
    @DisplayName("10 分钟平均 16.99m/s 不触发")
    void belowThresholdDoesNotTrigger() throws Exception {
        feedWind(segmentIds.get(0), T0, 10, new BigDecimal("16.99"), "below");
        assertThat(lineStatus()).isEqualTo("NORMAL");
        assertThat(countRows("control_event")).isZero();
    }

    @Test
    @DisplayName("乱序到达按时刻归位：后到的历史分钟补齐窗口后触发")
    void outOfOrderReadingCompletesWindow() throws Exception {
        // 先到 09:01~09:09 共 9 分钟，窗口缺 09:00，不触发
        feedWind(segmentIds.get(0), T0.plusMinutes(1), 9, new BigDecimal("18.00"), "ooo-head");
        assertThat(lineStatus()).isEqualTo("NORMAL");
        // 乱序补到 09:00，窗口 [09:00,09:09] 恰满 10 分钟，平均 18m/s → 缓停
        mockMvc.perform(post("/api/lines/{lineId}/wind-readings", lineId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(windJson("ooo-tail", segmentIds.get(0), T0, "18.00")))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.triggeredEvent.eventType").value("SOFT_HOLD"))
                .andExpect(jsonPath("$.triggeredEvent.windowStart").value("2026-01-10T09:00"))
                .andExpect(jsonPath("$.triggeredEvent.windowEnd").value("2026-01-10T09:09"));
        assertThat(lineStatus()).isEqualTo("SOFT_HOLD");
    }

    @Test
    @DisplayName("同分段同时刻数据去重：重复上报不产生新记录")
    void duplicateReadingIsDeduplicated() throws Exception {
        String body = windJson("dup-1", segmentIds.get(0), T0, "12.34");
        mockMvc.perform(post("/api/lines/{lineId}/wind-readings", lineId)
                        .contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.accepted").value(true));
        // 不同 requestId、同分段同时刻：按站点与时刻去重
        mockMvc.perform(post("/api/lines/{lineId}/wind-readings", lineId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(windJson("dup-2", segmentIds.get(0), T0, "12.34")))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.duplicate").value(true))
                .andExpect(jsonPath("$.accepted").value(false));
        assertThat(countRows("wind_reading")).isOne();
    }

    @Test
    @DisplayName("管制事件归档后，窗口内迟到数据只记迟到事件")
    void lateReadingOnlyRecordedAsLateEvent() throws Exception {
        feedWind(segmentIds.get(0), T0, 10, new BigDecimal("20.00"), "late-trigger");
        assertThat(lineStatus()).isEqualTo("EMERGENCY_STOP");
        // 测量时刻落在已判定窗口 [09:00,09:09] 内：迟到
        mockMvc.perform(post("/api/lines/{lineId}/wind-readings", lineId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(windJson("late-1", segmentIds.get(0), T0.plusMinutes(5), "30.00")))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.late").value(true))
                .andExpect(jsonPath("$.accepted").value(false));
        assertThat(countRows("late_wind_event")).isOne();
        // 迟到数据不进入正常风速表
        assertThat(countRows("wind_reading")).isEqualTo(10);
    }

    @Test
    @DisplayName("管制期间新风速照常入库去重，但不产生新管制事件")
    void readingsDuringControlDoNotTriggerNewEvent() throws Exception {
        feedWind(segmentIds.get(0), T0, 10, new BigDecimal("18.00"), "during-trigger");
        assertThat(lineStatus()).isEqualTo("SOFT_HOLD");
        // 管制期间另一分段也上报超阈值数据：入库但不触发新事件
        feedWind(segmentIds.get(1), T0.plusMinutes(10), 10, new BigDecimal("25.00"), "during-seg2");
        assertThat(countRows("control_event")).isOne();
        assertThat(countRows("wind_reading")).isEqualTo(20);
        assertThat(lineStatus()).isEqualTo("SOFT_HOLD");
    }
}

package com.example.starter;

import static org.assertj.core.api.Assertions.assertThat;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import java.math.BigDecimal;
import java.time.LocalDateTime;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.http.MediaType;

/**
 * 缓停全流程测试：禁止上客、逐段放行、复开 15 分钟规则与双岗确认。
 */
class SoftHoldFlowTest extends BaseIntegrationTest {

    private static final LocalDateTime T0 = LocalDateTime.of(2026, 2, 1, 10, 0, 0);

    private long eventId;

    @BeforeEach
    void triggerSoftHold() throws Exception {
        feedWind(segmentIds.get(0), T0, 10, new BigDecimal("17.50"), "soft-flow");
        assertThat(lineStatus()).isEqualTo("SOFT_HOLD");
        eventId = jdbc.queryForObject("SELECT id FROM control_event", Long.class);
    }

    @Test
    @DisplayName("缓停期间线路禁止上客")
    void boardingForbiddenDuringSoftHold() throws Exception {
        mockMvc.perform(get("/api/lines/{lineId}", lineId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("SOFT_HOLD"))
                .andExpect(jsonPath("$.boardingAllowed").value(false));
    }

    @Test
    @DisplayName("在途吊厢须按站点逐段放行：跳段放行被拒绝")
    void releaseMustFollowStationOrder() throws Exception {
        // 直接放行第 2 段：违反顺序
        mockMvc.perform(post("/api/events/{eventId}/segment-releases", eventId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"rel-o1\",\"segmentId\":" + segmentIds.get(1) + "}"))
                .andExpect(status().isUnprocessableEntity())
                .andExpect(jsonPath("$.code").value("RELEASE_OUT_OF_ORDER"));
        // 按序放行 1、2、3 段
        for (int i = 0; i < segmentIds.size(); i++) {
            var result = mockMvc.perform(post("/api/events/{eventId}/segment-releases", eventId)
                            .contentType(MediaType.APPLICATION_JSON)
                            .content("{\"requestId\":\"rel-" + i + "\",\"segmentId\":" + segmentIds.get(i) + "}"))
                    .andExpect(status().isOk())
                    .andExpect(jsonPath("$.releasedSegmentSeq").value(i + 1));
            if (i == segmentIds.size() - 1) {
                result.andExpect(jsonPath("$.allReleased").value(true));
            }
        }
        assertThat(countRows("segment_release")).isEqualTo(3);
    }

    @Test
    @DisplayName("低风速持续 14 分钟申请复开被拒，恰满 15 分钟允许申请")
    void reopenRequiresFullFifteenMinutes() throws Exception {
        LocalDateTime calm = T0.plusMinutes(10);
        // 仅 14 分钟低于 15m/s：不满足
        for (long seg : segmentIds) {
            feedWind(seg, calm, 14, new BigDecimal("10.00"), "calm14-" + seg);
        }
        mockMvc.perform(post("/api/events/{eventId}/reopen-requests", eventId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"reopen-early\"}"))
                .andExpect(status().isUnprocessableEntity())
                .andExpect(jsonPath("$.code").value("WIND_NOT_RECOVERED"));
        // 补足第 15 分钟（恰满 15 分钟允许申请）
        for (long seg : segmentIds) {
            feedWind(seg, calm.plusMinutes(14), 1, new BigDecimal("10.00"), "calm15-" + seg);
        }
        mockMvc.perform(post("/api/events/{eventId}/reopen-requests", eventId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"reopen-ok\"}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.status").value("PENDING"));
    }

    @Test
    @DisplayName("复开须运营与机务双岗确认：单岗确认不复开，同岗重复确认被拒")
    void reopenRequiresDualRoleConfirmation() throws Exception {
        feedCalmFifteen();
        String reopenBody = mockMvc.perform(post("/api/events/{eventId}/reopen-requests", eventId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"reopen-dual\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        long reopenId = com.jayway.jsonpath.JsonPath.read(reopenBody, "$.reopenRequestId");

        // 运营岗确认：仍未复开
        mockMvc.perform(post("/api/reopen-requests/{id}/confirmations", reopenId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"conf-ops\",\"role\":\"OPERATIONS\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.approved").value(false));
        assertThat(lineStatus()).isEqualTo("SOFT_HOLD");
        // 同岗重复确认：422
        mockMvc.perform(post("/api/reopen-requests/{id}/confirmations", reopenId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"conf-ops-2\",\"role\":\"OPERATIONS\"}"))
                .andExpect(status().isUnprocessableEntity())
                .andExpect(jsonPath("$.code").value("DUPLICATE_CONFIRMATION"));
        // 机务岗确认：复开，事件归档为终态
        mockMvc.perform(post("/api/reopen-requests/{id}/confirmations", reopenId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"conf-mnt\",\"role\":\"MAINTENANCE\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.approved").value(true))
                .andExpect(jsonPath("$.eventStatus").value("CLOSED"));
        assertThat(lineStatus()).isEqualTo("NORMAL");
        String eventStatus = jdbc.queryForObject("SELECT status FROM control_event WHERE id = ?",
                String.class, eventId);
        assertThat(eventStatus).isEqualTo("CLOSED");
        // 归档后窗口内迟到数据只记迟到事件
        mockMvc.perform(post("/api/lines/{lineId}/wind-readings", lineId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(windJson("late-after-close", segmentIds.get(0), T0.plusMinutes(3), "40.00")))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.late").value(true));
        assertThat(countRows("late_wind_event")).isOne();
    }

    @Test
    @DisplayName("复开后线路恢复允许上客")
    void boardingAllowedAfterReopen() throws Exception {
        feedCalmFifteen();
        String reopenBody = mockMvc.perform(post("/api/events/{eventId}/reopen-requests", eventId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"reopen-board\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        long reopenId = com.jayway.jsonpath.JsonPath.read(reopenBody, "$.reopenRequestId");
        mockMvc.perform(post("/api/reopen-requests/{id}/confirmations", reopenId)
                .contentType(MediaType.APPLICATION_JSON)
                .content("{\"requestId\":\"cb-1\",\"role\":\"OPERATIONS\"}"));
        mockMvc.perform(post("/api/reopen-requests/{id}/confirmations", reopenId)
                .contentType(MediaType.APPLICATION_JSON)
                .content("{\"requestId\":\"cb-2\",\"role\":\"MAINTENANCE\"}"));
        mockMvc.perform(get("/api/lines/{lineId}", lineId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("NORMAL"))
                .andExpect(jsonPath("$.boardingAllowed").value(true));
    }

    /** 为所有分段补足恰满 15 分钟低于 15m/s 的风速数据。 */
    private void feedCalmFifteen() throws Exception {
        LocalDateTime calm = T0.plusMinutes(10);
        for (long seg : segmentIds) {
            feedWind(seg, calm, 15, new BigDecimal("10.00"), "calm15full-" + seg);
        }
    }
}

